<script setup lang="ts">
import { Head, Link, useForm } from '@inertiajs/vue3';
import { ref } from 'vue';
import AccountLayout from '../../../layouts/AccountLayout.vue';
import ProductImages from '../../../components/ProductImages.vue';
import StatusBadge from '../../../components/StatusBadge.vue';

import { statusLabel, type Product, type Taxonomy, type Specification, type CatalogStatus } from '../../../types/catalog';
import { freshnessLabel, needsAttention, stockLabel, type Freshness } from '../../../types/freshness';
const props = defineProps<{ product: Product | null; categories: Taxonomy[]; brands: Taxonomy[]; canManage: boolean; freshness: Freshness | null }>();
const when = (iso: string | null) => iso ? new Date(iso).toLocaleString('es-CR', { dateStyle: 'short', timeStyle: 'short' }) : '';
const p = props.product;
const form = useForm({ name: p?.name ?? '', sku: p?.sku ?? '', slug: p?.slug ?? '', category_id: p?.category_id ?? '', brand_id: p?.brand_id ?? '', short_description: p?.short_description ?? '', description: p?.description ?? '', warranty: p?.warranty ?? '', specifications: (p?.specifications ?? []).map(spec => ({ ...spec })) as Specification[], price_minor: p?.price_minor ?? 0, previous_price_minor: p?.previous_price_minor ?? null as number | null, currency: p?.currency ?? 'CRC', featured: p?.featured ?? false, meta_title: p?.meta_title ?? '', meta_description: p?.meta_description ?? '' });
const price = ref(p ? (p.price_minor / 100).toFixed(2) : '');
const previous = ref(p?.previous_price_minor ? (p.previous_price_minor / 100).toFixed(2) : '');
const publication = useForm({ status: p?.status ?? 'draft' as CatalogStatus });
function minor(value: string): number { const normalized = value.trim().replace(',', '.'); if (!/^\d{1,10}(\.\d{1,2})?$/.test(normalized)) return -1; const [whole, fraction = ''] = normalized.split('.'); return Number(whole) * 100 + Number(fraction.padEnd(2, '0')); }
function save() { form.price_minor = minor(price.value); form.previous_price_minor = previous.value.trim() ? minor(previous.value) : null; if (props.product) form.put(`/admin/catalog/products/${props.product.id}`, { preserveScroll: true }); else form.post('/admin/catalog/products'); }
function status(value: CatalogStatus) { publication.status = value; publication.patch(`/admin/catalog/products/${props.product?.id}/status`, { preserveScroll: true }); }
</script>
<template><Head :title="product ? product.name : 'Nuevo producto'"/><AccountLayout :title="product ? 'Detalle de producto' : 'Crear producto'" section="admin"><Link href="/admin/catalog/products" class="quiet-link">← Volver al catálogo</Link><p v-if="!canManage" class="notice">Consulta de operator: no tienes permisos de modificación.</p><p v-if="product?.is_demo" class="notice">Producto de demostración. No representa stock, precios ni acuerdos reales.</p><section v-if="product" class="info-card is-work"><div class="catalog-toolbar"><StatusBadge :status="product.status"/><template v-if="canManage"><button v-if="product.status !== 'published' && product.status !== 'archived'" class="button" :disabled="publication.processing" @click="status('published')">Publicar</button><button v-if="product.status !== 'draft'" class="quiet-link" :disabled="publication.processing" @click="status('draft')">{{ product.status === 'archived' ? 'Restaurar a borrador' : 'Despublicar' }}</button><button v-if="product.status !== 'archived'" class="quiet-link" :disabled="publication.processing" @click="status('archived')">Archivar</button></template><Link v-if="product.status === 'published'" :href="`/catalog/${product.slug}`" class="quiet-link">Vista pública ↗</Link></div><p v-for="(error, key) in publication.errors" :key="key" class="field-error" role="alert">{{ error }}</p><small class="muted">La categoría, sus superiores y la marca también deben estar publicados.</small></section><section v-if="product && freshness" class="info-card is-consult freshness-card" aria-labelledby="freshness-title"><p id="freshness-title" class="eyebrow">DISPONIBILIDAD EN EL CATÁLOGO</p><p><span class="freshness" :class="`is-${freshness.level}`">{{ freshnessLabel(freshness) }}</span><span v-if="stockLabel(freshness)" class="muted"> · {{ stockLabel(freshness) }}</span></p><p v-if="freshness.observed_at" class="muted">Observada {{ when(freshness.observed_at) }}<template v-if="freshness.expires_at"> · vence {{ when(freshness.expires_at) }}</template></p><p v-if="freshness.level === 'expired'" class="muted">El producto no se muestra en el catálogo público hasta que registres una observación nueva de la oferta.</p><p v-else-if="freshness.level === 'invalid'" class="muted">La oferta está inactiva, su fecha está en el futuro o no tiene stock confirmado: el producto no se muestra.</p><p v-else-if="freshness.level === 'none'" class="muted">Sin oferta preferida el producto no se muestra en el catálogo público.</p><Link :href="`/admin/commercial/products/${product.id}`" :class="needsAttention(freshness) ? 'button small' : 'quiet-link'">{{ needsAttention(freshness) ? 'Actualizar oferta' : 'Ver ofertas' }} →</Link></section><div class="product-columns"><form class="compact-form info-card is-work product-form" @submit.prevent="save"><fieldset :disabled="!canManage || form.processing"><h2>Información comercial</h2><div class="form-grid"><label>Nombre<input v-model="form.name" required maxlength="180"></label><label>SKU interno<input v-model="form.sku" class="code" required maxlength="64"></label><label>Slug<input v-model="form.slug" maxlength="180" placeholder="Se genera del nombre si se deja vacío"></label><label>Marca<select v-model="form.brand_id" required><option value="" disabled>Seleccionar</option><option v-for="brand in brands" :key="brand.id" :value="brand.id" :disabled="brand.status === 'archived'">{{ brand.name }} ({{ statusLabel(brand.status) }})</option></select></label><label>Categoría<select v-model="form.category_id" required><option value="" disabled>Seleccionar</option><option v-for="category in categories" :key="category.id" :value="category.id" :disabled="category.status === 'archived'">{{ category.name }} ({{ statusLabel(category.status) }})</option></select></label><label>Moneda<select v-model="form.currency"><option value="CRC">CRC · Colones</option><option value="USD">USD · Dólares</option></select></label><label>Precio público<input v-model="price" inputmode="decimal" required placeholder="125000.00"><small>Importe en {{ form.currency }}, hasta dos decimales.</small></label><label>Precio anterior (opcional)<input v-model="previous" inputmode="decimal" placeholder="Debe ser mayor al precio público"></label></div><label>Descripción corta<textarea v-model="form.short_description" required maxlength="500"/></label><label>Descripción completa<textarea v-model="form.description" required maxlength="20000" rows="6"/></label><label>Garantía<textarea v-model="form.warranty" maxlength="3000"/></label><label class="inline-choice"><input v-model="form.featured" type="checkbox"> Producto destacado</label><h2>Especificaciones técnicas</h2><p class="muted">Claves estables como ram_gb o screen_size. Define valor, unidad y grupo sin agregar columnas al producto.</p><div class="spec-list"><div v-for="(spec, index) in form.specifications" :key="index" class="spec-editor"><label><span class="spec-label">Clave</span><input v-model="spec.key" required placeholder="ej. ram_gb" maxlength="60"></label><label><span class="spec-label">Etiqueta</span><input v-model="spec.label" required placeholder="ej. Memoria RAM" maxlength="100"></label><label><span class="spec-label">Valor</span><input v-model="spec.value" required placeholder="ej. 16" maxlength="500"></label><label><span class="spec-label">Unidad</span><input v-model="spec.unit" placeholder="opcional" maxlength="30"></label><label><span class="spec-label">Grupo</span><input v-model="spec.group" placeholder="opcional" maxlength="80"></label><button v-if="canManage" type="button" class="quiet-link" @click="form.specifications.splice(index, 1)">Quitar</button></div></div><button v-if="canManage" type="button" class="quiet-link mt-4" :disabled="form.specifications.length >= 50" @click="form.specifications.push({ key: '', label: '', value: '', unit: '', group: '' })">+ Agregar especificación</button><h2>SEO básico</h2><label>Título SEO<input v-model="form.meta_title" maxlength="70"></label><label>Descripción SEO<textarea v-model="form.meta_description" maxlength="170"/></label><p class="muted">Si quedan vacíos se usan el nombre y la descripción corta.</p><p v-for="(error, key) in form.errors" :key="key" class="field-error" role="alert">{{ error }}</p><button v-if="canManage" class="button full" :disabled="form.processing">Guardar producto</button></fieldset></form><section v-if="product" class="info-card is-work"><h2>Ofertas y precio sugerido</h2><p>Gestiona costos privados, oferta preferida y reglas sin cambiar el precio publicado hasta que decidas aplicarlo.</p><Link :href="`/admin/commercial/products/${product.id}`" class="button">Abrir ofertas y precios</Link></section><div class="product-side"><ProductImages v-if="product" :product-id="product.id" :images="product.images" :can-manage="canManage"/></div></div></AccountLayout></template>
